Item.sk_method_code:
    // 新規作成時は設定画面を表示するため処理なし
    const itemId = document.thisItem.getProperty('id');
    if (typeof itemId === 'undefined' || itemId == '') {
        return;
    }
    
    const inn = new Innovator();

    const identityList = aras.getIdentityList();
    const identityListArray = identityList.split(',');
    var adminCheck = true; // 表示・非表示の切り替え判定用
/*    
    // 現在開こうとしているアイテムのowned_by_idとcreated_by_idを取得
    const owned_by_id = document.thisItem.getProperty('owned_by_id');
    const created_by_id = document.thisItem.getProperty('created_by_id');
*/
    // owned_by_idかcreated_by_idかAdministratorsに所属しているか確認
    for (var i = 0; i < identityListArray.length; i++) {
        const identity = inn.getItemById("Identity", identityListArray[i]);
        const identityKeyedName = identity.getProperty('keyed_name');
        const identityId = identity.getProperty('id');
        // Administratorsか、owned_by_idかcreated_by_idに所属している場合、adminCheckにfalseを入れる
        if (identityKeyedName == 'Administrators') {
            adminCheck = false;
            break;
        }
    }
    
    const accordions = parent.document.getElementsByClassName("aras-accordion");
    if (accordions && accordions.length > 0) {
        accordions[0].toggle(adminCheck);  // true: Close, false: Open
    }

    return;
